export const BODY: string = "\n<p>تصویر سے میٹا ڈیٹا ہٹانے میں ایک منٹ سے کم لگتا ہے۔ آپ تصویر اپ لوڈ کرتے ہیں، ٹول چھپا ڈیٹا ہٹاتا ہے، اور آپ صاف کاپی ڈاؤن لوڈ کرتے ہیں۔</p>\n<p>یہ رہنما مفت <a href=\"/ur/tasveer-metadata-hatayein/\">Remove Image Metadata</a> ٹول کے ساتھ ہر مرحلہ بتاتا ہے۔ یہ آپ کے براؤزر میں کام کرتا ہے، اکاؤنٹ نہیں چاہیے، اور آپ کی تصویریں کبھی کہیں اپ لوڈ نہیں ہوتیں۔</p>\n<p>آخر تک آپ جان جائیں گے کہ ایک تصویر کیسے صاف کریں، پورا بیچ کیسے صاف کریں، درست ہٹانے کا طریقہ کیسے چنیں، اور نتیجہ صاف ہے کیسے ثابت کریں۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے آپ کو کیا چاہیے</h2>\n<p>آپ کو وہ تصویر فائل چاہیے جسے آپ شیئر کرنے کا ارادہ رکھتے ہیں، اپنے آلے پر محفوظ۔ اصل فائل سے کام کریں، اس کاپی سے نہیں جو آپ کہیں پہلے پوسٹ کر چکے ہیں۔</p>\n<p>ٹول 20 MB تک JPG، PNG، WebP اور HEIC فائلیں قبول کرتا ہے۔ یہ فون کی تصویروں، DSLR JPEG، PNG برآمدات اور آئی فون HEIC فائلوں کو پورا کرتا ہے۔</p>\n<p>اگر میٹا ڈیٹا آپ کے لیے اہم ہو تو اصل کی نجی کاپی رکھیں۔ صاف شدہ کاپی کے لیے ہٹانا مستقل ہے، اور کیمرہ ترتیبات یا GPS ڈیٹا اس سے بعد میں واپس نہیں لایا جا سکتا۔</p>\n<h2 id=\"step-1-open-the-tool\">مرحلہ 1: ٹول کھولیں</h2>\n<p><a href=\"/ur/tasveer-metadata-hatayein/\">Remove Image Metadata</a> صفحے پر جائیں۔ آپ کو اپ لوڈ ڈبہ اور ٹول کیا کرتا ہے، اس کی مختصر وضاحت دکھائی دے گی۔</p>\n<p>سائن ان اسکرین نہیں ہے اور پے وال نہیں ہے۔ ٹول مفت ہے، اور آپ صفر واٹر مارک یا فیس کے ساتھ لامحدود تصویریں صاف کر سکتے ہیں۔</p>\n<p>فون پر صفحہ موبائل سفاری یا کروم میں کھولیں۔ لے آؤٹ ڈھل جاتا ہے، اور آپ اپنے کیمرہ رول سے سیدھی تصویریں چن سکتے ہیں۔</p>\n<h2 id=\"step-2-upload-photos\">مرحلہ 2: اپنی تصویریں اپ لوڈ کریں</h2>\n<p>تصویریں اپ لوڈ ڈبے میں گھسیٹ دیں، یا اپنے آلے سے فائلیں چننے کے لیے اس پر کلک کریں۔ آپ ایک تصویر یا پورا بیچ ایک ساتھ ڈال سکتے ہیں۔</p>\n<p>آپ ونڈوز پر Ctrl+V یا میک پر Cmd+V سے چسپاں بھی کر سکتے ہیں۔ کاپی شدہ تصویر یا اسکرین شاٹ سیدھا اپ لوڈ قطار میں آتا ہے اور خود بخود صاف ہو جاتا ہے۔</p>\n<p>اپ لوڈ پر صفائی فوراً شروع ہوتی ہے۔ دبانے کو کوئی شروع بٹن نہیں، اور سرور کا کوئی انتظار نہیں، کیونکہ سارا کام آپ کے براؤزر میموری کے اندر ہوتا ہے۔</p>\n<h2 id=\"step-3-check-badges\">مرحلہ 3: تصدیقی بیج جانچیں</h2>\n<p>اپ لوڈ کے بعد ہر کارڈ خود بخود دوبارہ اسکین کرتا ہے اور دکھاتا ہے کہ کتنے میٹا ڈیٹا ٹیگ ہٹائے گئے، مثال کے طور پر Stripped X metadata tags to 0 remaining۔</p>\n<p>سبز یا زمرد بیج کا مطلب ہے آؤٹ پٹ صاف تصدیق ہوا۔ ٹول آؤٹ پٹ فائل پر اپنا میٹا ڈیٹا پارسر دوسری بار چلاتا ہے، اس لیے بیج حقیقی جانچ ہے، اندازہ نہیں۔</p>\n<p>اگر اپ لوڈ کے فوراً بعد کسی تصویر پر Verified clean دکھائی دے تو ماخذ میں پہلے سے صفر EXIF، GPS یا متن حصے تھے۔ اسکرین شاٹ اور پیغام ایپس سے ڈاؤن لوڈ شدہ تصویریں عام طور پر اسی طرح آتی ہیں۔</p>\n<h2 id=\"step-4-choose-method\">مرحلہ 4: ہٹانے کا طریقہ چنیں</h2>\n<p>پہلے سے طے شدہ طریقہ Lossless Binary Strip ہے، اور یہ زیادہ تر JPG اور PNG تصویروں کے لیے درست انتخاب ہے۔ یہ ایک بھی پکسل ڈی کوڈ یا دوبارہ کمپریس کیے بغیر میٹا ڈیٹا حصے ہٹاتا ہے۔</p>\n<p>جب آپ صفر کوالٹی تبدیلی چاہیں تو یہ طریقہ رکھیں۔ آپ کا JPG JPG رہتا ہے، آپ کا PNG PNG رہتا ہے، اور شفاف PNG پس منظر بائٹ بہ بائٹ بچتے ہیں۔</p>\n<p>جب آپ بغیر کسی ورثہ حصے کے بالکل نیا بٹ میپ چاہیں تو Full Canvas Re-encode چنیں۔ یہ WebP اور HEIC ان پٹ کے لیے بھی خود بخود استعمال ہوتا ہے، اور جب بھی آپ آؤٹ پٹ فارمیٹ بدلیں۔</p>\n<h2 id=\"step-5-format-quality\">مرحلہ 5: آؤٹ پٹ فارمیٹ اور کوالٹی طے کریں</h2>\n<p>پہلے سے طے شدہ طور پر ٹول اصل فارمیٹ رکھتا ہے، اس لیے JPG JPG رہتا ہے اور PNG PNG رہتا ہے۔ یہ محفوظ ترین انتخاب ہے جب آپ صرف میٹا ڈیٹا ہٹانا چاہیں۔</p>\n<p>صفائی کے دوران بدلنے کے لیے Output Format کے نیچے JPG، PNG یا WebP چنیں۔ ہر فائل کینوس سے صاف دوبارہ انکوڈ ہوتی ہے، تمام میٹا ڈیٹا ہٹا کر اور چنا ہوا فارمیٹ لگا کر۔</p>\n<p>دونوں طریقوں کے مکمل موازنہ کے لیے <a href=\"/ur/blog/tasveer-metadata-hatayein-rehnumai/\">Remove Image Metadata: Complete Guide</a> پڑھیں۔ ترتیبات بدلنے کے بعد Re-clean All پر کلک کریں، تاکہ نئے اختیار پورے بیچ پر لاگو ہوں۔</p>\n<h2 id=\"step-6-download\">مرحلہ 6: صاف فائلیں ڈاؤن لوڈ کریں</h2>\n<p>جب بیج سبز ہوں تو اپنی فائلیں ڈاؤن لوڈ کریں۔ وہ تصویر محفوظ کرنے کے لیے کسی کارڈ پر Download Clean پر کلک کریں، یا پورے بیچ کے لیے Download All Clean (ZIP) پر کلک کریں۔</p>\n<p>ZIP فائل کا نام clean_images_no_metadata.zip ہے۔ اس میں بیچ کی ہر صاف شدہ تصویر ہے، مارکیٹ پلیس، فورم یا لسٹنگ میں اپ لوڈ کے لیے تیار۔</p>\n<p>ڈاؤن لوڈ الگ فائلیں ہیں۔ آپ کے اصل ڈسک پر اچھوتے رہتے ہیں، کیونکہ براؤزر آپ کے مقامی فولڈر میں فائلیں اوور رائٹ نہیں کر سکتے۔</p>\n<h2 id=\"step-7-verify\">مرحلہ 7: صاف شدہ فائل کی تصدیق کریں</h2>\n<p>تصدیق وہ مرحلہ ہے جسے زیادہ تر لوگ چھوڑ دیتے ہیں، اور یہ وہ مرحلہ ہے جو ثابت کرتا ہے کہ کام ہو گیا۔ ڈاؤن لوڈ شدہ صاف فائل کو <a href=\"/ur/tasveer-metadata-dekhein/\">Image Metadata Viewer</a> میں ڈالیں۔</p>\n<p>اگر صفائی کامیاب ہوئی تو سبز بینر تصدیق کرتا ہے کہ کوئی EXIF، GPS یا چھپے کیمرہ ٹیگ نہیں ملے، اور کوئی GPS انتباہ نہیں دکھائی دیتا۔ یہ فائل بائٹ کی آزاد جانچ ہے۔</p>\n<p>اگر ٹیگ باقی رہیں تو ویور جدول بالکل دکھاتا ہے کہ کون سے بچ گئے۔ عام بچ جانے والے PNG متن حصے اور JPEG تبصرے ہیں، جو کچھ صاف کرنے والے چھوڑ دیتے ہیں۔</p>\n<h2 id=\"cleaning-on-mobile\">فون پر میٹا ڈیٹا ہٹانا</h2>\n<p>زیادہ تر تصویریں فون سے شیئر ہوتی ہیں، اس لیے ورک فلو موبائل براؤزر میں کام کرتا ہے۔ ٹول iOS سفاری یا اینڈرائیڈ کروم میں کھولیں اور اپنے کیمرہ رول سے تصویریں چنیں۔</p>\n<p>فائلیں اپ لوڈ پر صاف ہوتی ہیں، بیج سبز ہو جاتے ہیں، اور آپ صاف کاپیاں سیدھا اپنے آلے پر ڈاؤن لوڈ کرتے ہیں۔ پھر صاف شدہ فائلیں اپنی گیلری سے شیئر کریں۔</p>\n<p>سوشل یا مارکیٹ پلیس ایپ کھولنے سے پہلے صاف کریں، بعد میں نہیں۔ ایک بار تصویر پوسٹ ہو جائے تو کوئی بھی اصل کو اس کے میٹا ڈیٹا سمیت ڈاؤن لوڈ کر چکا ہو سکتا ہے۔</p>\n<h2 id=\"cleaning-batches\">مارکیٹ پلیس کے لیے بیچ صاف کرنا</h2>\n<p>بیچنے والے گھر پر مصنوعات کی تصویریں لیتے ہیں، اور وہ تصویریں GPS کوآرڈینیٹ رکھ سکتی ہیں جو سیدھا بیچنے والے کے پتے کی طرف اشارہ کرتے ہیں۔ بیچ صفائی اس خطرے کو پوری شوٹ کے لیے ایک ساتھ ہٹا دیتی ہے۔</p>\n<p>لسٹنگ تصویروں کا پورا سیٹ ایک ساتھ ڈالیں اور تمام کارڈوں پر بیج سبز ہونے کا انتظار کریں۔ پھر Download All Clean (ZIP) پر کلک کریں اور صاف شدہ فائلیں لسٹنگ میں اپ لوڈ کریں۔</p>\n<p>اسی معمول کو فورم پوسٹ، کرایہ لسٹنگ اور درجہ بند اشتہارات کے لیے استعمال کریں۔ جہاں بھی اجنبی مکمل ریزولوشن تصویریں ڈاؤن لوڈ کریں، میٹا ڈیٹا ہٹانے کے قابل خطرہ ہے۔</p>\n<h2 id=\"troubleshooting-removal\">مسئلہ حل کرنا: جب صفائی توقع کے مطابق کام نہ کرے</h2>\n<p>زیادہ تر مسائل کی سادہ وجہ ہوتی ہے۔ ٹول ٹوٹا ہوا ماننے سے پہلے نیچے کی فہرست سے کام کریں۔</p>\n<ul>\n<li>صفائی کے بعد تصویر ترچھی لگتی ہے۔ بغیر نقصان والے ہٹانے نے EXIF سمت جھنڈا حذف کر دیا۔ Full Canvas Re-encode پر جائیں اور Re-clean All پر کلک کریں تاکہ سیدھی سمت پکسل میں پکا ہو جائے۔</li>\n<li>صفائی کے بعد بھی فائل ٹیگ دکھاتی ہے۔ کچھ PNG متن حصے یا JPEG تبصرے پہلے پاس میں بچ سکتے ہیں۔ Full Canvas Re-encode آزمائیں، جو تصویر نئے سرے سے بناتا ہے۔</li>\n<li>کوالٹی سلائیڈر کچھ نہیں کرتا لگتا۔ یہ صرف WebP اور HEIC ان پٹ، یا Full Canvas Re-encode برآمدات پر لاگو ہوتا ہے۔ Lossless Binary Strip کبھی پکسل دوبارہ انکوڈ نہیں کرتا، اس لیے وہاں سلائیڈر کا کوئی اثر نہیں۔</li>\n<li>فائل اپ لوڈ نہیں ہوتی۔ سائز جانچیں: حد فی فائل 20 MB ہے۔ پہلے تصویر کمپریس کریں، پھر چھوٹی کاپی صاف کریں۔</li>\n<li>ڈاؤن لوڈ شدہ فائل اصل جیسی لگتی ہے۔ یہ درست ہے۔ صفائی چھپا ڈیٹا ہٹاتی ہے، پکسل نہیں، اس لیے کامیاب صفائی اصل جیسی ہی لگتی ہے۔</li>\n<li>بیج فوراً Verified clean کہتا ہے۔ ماخذ میں پہلے سے کوئی میٹا ڈیٹا نہیں تھا، جو اسکرین شاٹ اور پیغام ایپس کی تصویروں کے لیے عام ہے۔ کچھ بھی غلط نہیں تھا۔</li>\n</ul>\n<p>اگر مسئلہ برقرار رہے تو کیمرہ رول سے سیدھا تازہ اصل سے آزمائیں۔ اس سے معلوم ہوتا ہے کہ وجہ فائل ہے یا ترتیبات۔</p>\n<h2 id=\"heic-photos\">HEIC تصویروں سے میٹا ڈیٹا ہٹانا</h2>\n<p>آئی فون کی تصویریں اکثر HEIC فائلوں کے طور پر آتی ہیں، اور انہیں تھوڑا مختلف ہینڈلنگ چاہیے۔ ٹول JPG اور PNG کی طرح 20 MB تک HEIC اپ لوڈ قبول کرتا ہے۔</p>\n<p>HEIC فائلیں Lossless Binary Strip سے نہیں ہٹائی جاتیں۔ اس کی بجائے ٹول پکسل کو تازہ کینوس پر بناتا ہے، جو یقینی کرتا ہے کہ تمام میٹا ڈیٹا ہیڈر گر جائیں۔</p>\n<p>اس کا مطلب ہے کہ HEIC صفائی ہمیشہ دوبارہ انکوڈ ہے۔ ڈاؤن لوڈ سے پہلے Re-encode Quality سلائیڈر طے کریں: 85 فیصد کے قریب اچھا پہلے سے طے شدہ ہے، اور 90 سے 100 فیصد سب سے زیادہ تفصیل رکھتا ہے۔</p>\n<h2 id=\"after-downloading\">ڈاؤن لوڈ کے بعد کیا کریں</h2>\n<p>صاف فائل ڈاؤن لوڈ کرنا آخری مرحلہ نہیں۔ ڈاؤن لوڈ کے بعد چند چھوٹی عادتیں یقینی کرتی ہیں کہ صاف کاپی ہی وہ ہے جو اصل میں شیئر ہوتی ہے۔</p>\n<p>پہلا، فائل نام جانچیں۔ صاف شدہ ڈاؤن لوڈ اصل کے ساتھ نام شیئر کر سکتا ہے، اس لیے اسے الگ فولڈر میں رکھیں تاکہ دونوں الجھ نہ جائیں۔</p>\n<p>دوسرا، ہر بیچ سے کم از کم ایک فائل کی تصدیق کریں۔ صاف شدہ کاپی ویور میں کھولیں اور کہیں اپ لوڈ کرنے سے پہلے سبز بغیر ٹیگ بینر کی تصدیق کریں۔</p>\n<h2 id=\"how-to-remove-summary\">فوری خلاصہ</h2>\n<p><a href=\"/ur/tasveer-metadata-hatayein/\">Remove Image Metadata</a> ٹول کھولیں، اپنی تصویریں ڈالیں، اور سبز تصدیقی بیج کا انتظار کریں۔ JPG اور PNG کے لیے Lossless Binary Strip چنیں، یا WebP، HEIC، فارمیٹ تبدیلی یا ترچھی تصویروں کے لیے Full Canvas Re-encode چنیں۔</p>\n<p>صاف فائلیں یا ZIP ڈاؤن لوڈ کریں، پھر ایک کو <a href=\"/ur/tasveer-metadata-dekhein/\">Image Metadata Viewer</a> میں تصدیق کریں۔ جب سبز بینر دکھائی دے تو تصویر شیئر کے لیے محفوظ ہے۔</p>\n<p>پورا معمول ایک منٹ سے کم لگتا ہے۔ اسے ہر عوامی پوسٹ سے پہلے عادت بنائیں، اور آپ کی تصویریں صرف وہی رکھیں گی جو آپ نے شیئر کرنا چنا۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"آئی فون پر تصویر سے میٹا ڈیٹا کیسے ہٹاؤں؟","answer":"موبائل سفاری میں Remove Image Metadata ٹول کھولیں، اپنے کیمرہ رول سے تصویر چنیں، اور سبز تصدیقی بیج کا انتظار کریں۔ پھر صاف کاپی اپنے آلے پر محفوظ کرنے کے لیے Download Clean پر ٹیپ کریں۔ صاف شدہ کاپی شیئر کریں، اپنے کیمرہ رول سے اصل نہیں۔"},{"question":"کیا اسکرین شاٹ سے میٹا ڈیٹا ہٹا سکتا ہوں؟","answer":"اسکرین شاٹ میں عام طور پر پہلے سے کوئی کیمرہ میٹا ڈیٹا نہیں ہوتا، کیونکہ کلپ بورڈ اصل کیمرہ فائل کی بجائے خام پکسل منتقل کرتا ہے۔ اسکرین شاٹ ٹول میں ڈالنے سے عام طور پر فوراً Verified clean دکھائی دیتا ہے۔ ٹول پھر بھی اسے جانچتا ہے، اس لیے اسے گزارنے سے آپ کچھ نہیں کھوتے۔"},{"question":"لسٹنگ لائیو جانے سے پہلے کئی تصویریں صاف کرنے کا تیز ترین طریقہ کیا ہے؟","answer":"پورا سیٹ ایک ساتھ ٹول میں ڈالیں، تمام کارڈوں پر سبز بیج کا انتظار کریں، اور Download All Clean (ZIP) پر کلک کریں۔ ZIP میں ہر صاف شدہ تصویر ایک فائل میں ہے۔ صاف شدہ فائلیں اپنی لسٹنگ میں اپ لوڈ کریں — اصل کبھی نہیں۔"},{"question":"کیا تصویر صاف کرنی ضروری ہے اگر میں اسے صرف ایک دوست کو بھیج رہا ہوں؟","answer":"یہ چینل پر منحصر ہے۔ واٹس ایپ جیسی پیغام ایپس میٹا ڈیٹا خود بخود ہٹا دیتی ہیں، اس لیے اس طرح بھیجی گئی تصویر عام طور پر صاف آتی ہے۔ ای میل منسلکات اور سیدھی فائل منتقلی اکثر اصل کو برقرار رکھتی ہیں، اس لیے اگر آپ اسے فائل کے طور پر بھیج رہے ہیں تو پہلے تصویر صاف کریں۔"},{"question":"میری صاف شدہ تصویر کا فائل سائز اصل سے چھوٹا کیوں ہے؟","answer":"کیمرہ تصویریں اکثر ایمبیڈ شدہ EXIF پیش نظارہ تھمب نیل، XMP بلاک اور تبصرہ حصے رکھتی ہیں۔ Lossless Binary Strip موڈ میں انہیں ہٹانے سے اکثر تصویر کی تیزی میں صفر تبدیلی کے ساتھ دسیوں کلو بائٹ کم ہو جاتے ہیں۔ چھوٹا سائز بونس ہے، کوالٹی نقصان کی علامت نہیں۔"},{"question":"کیا صاف فائل ڈاؤن لوڈ کرنے کے بعد میٹا ڈیٹا ہٹانا واپس کر سکتا ہوں؟","answer":"نہیں۔ صاف شدہ کاپی میں کوئی میٹا ڈیٹا باقی نہیں جسے بحال کیا جا سکے۔ اسی لیے آپ کو صاف کرنے سے پہلے اپنی اصل فائل نجی فولڈر میں رکھنی چاہیے۔ اصل اپنے کیمرہ ترتیبات اور GPS ڈیٹا اپنے ریکارڈ کے لیے رکھتا ہے، جبکہ صاف شدہ کاپی وہ ہے جو آپ شیئر کرتے ہیں۔"}];
